insert into public.programs(slug,title_en,description_en,status) values('core-mba','MBA Assistant Core','Independent non-degree business curriculum','published') on conflict(slug) do nothing;
with p as(select id from public.programs where slug='core-mba') insert into public.modules(program_id,sequence,title_en,summary_en,status) select p.id,x.n,x.t,x.s,'published'::public.content_status from p cross join(values(1,'Business Foundations','Value creation and managerial decisions'),(2,'Accounting & Finance','Financial literacy and investment decisions'),(3,'Marketing & Customers','Customer value and growth'),(4,'Operations & Supply Chain','Flow, quality and delivery'),(5,'Leadership & Organizations','People and change'),(6,'Business Strategy','Competitive advantage and execution'),(7,'Analytics & AI','Evidence-based decisions'),(8,'Communication, Negotiation & Ethics','Influence and responsible governance'),(9,'Innovation & Entrepreneurship','Build and test opportunities'),(10,'MBA Capstone','Integrated executive project'))as x(n,t,s) on conflict(program_id,sequence) do nothing;